package az.jeparla.common.persistence;

import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import org.hibernate.Hibernate;

/**
 * Entity with a {@code BIGINT GENERATED BY DEFAULT AS IDENTITY} primary key.
 *
 * <p>Equality is by id: two instances are equal when they are of the same entity class and
 * have the same non-null id. A new (unsaved) entity is only equal to itself. The hash code is
 * constant per class, so an entity keeps its bucket in a {@code HashSet} after it is saved.
 */
@MappedSuperclass
public abstract class LongIdEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    public Long getId() {
        return id;
    }

    @Override
    public final boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || Hibernate.getClass(this) != Hibernate.getClass(other)) {
            return false;
        }
        Long otherId = ((LongIdEntity) other).getId();
        return id != null && id.equals(otherId);
    }

    @Override
    public final int hashCode() {
        return Hibernate.getClass(this).hashCode();
    }

    @Override
    public String toString() {
        return Hibernate.getClass(this).getSimpleName() + "#" + id;
    }
}
